package com.baystudio.droide.core
import java.io.File
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [29, 35])
class GraphqlSelectionGenerationTest {
    @Test fun noOpAndTerminalNodeDoNotRevokeGraphql(){val p=WorkspaceToolchainPreferences(RuntimeEnvironment.getApplication(),File("/graphql-fixture-${System.nanoTime()}"));val t=p.graphqlSelectionGeneration();p.clear("lsp.graphql-library");assertTrue(p.isGraphqlSelectionGenerationCurrent(t));p.set("runtime.node","22.23.3");assertTrue(p.isGraphqlSelectionGenerationCurrent(t))}
    @Test fun onlyExactPrivateSelectionRevokes(){val p=WorkspaceToolchainPreferences(RuntimeEnvironment.getApplication(),File("/graphql-fixture-${System.nanoTime()}"));val old=p.tomlSelectionGeneration();val g=p.graphqlSelectionGeneration();p.set("lsp.graphql-library","5.7.0");assertFalse(p.isGraphqlSelectionGenerationCurrent(g));assertTrue(p.isTomlSelectionGenerationCurrent(old));val n=p.graphqlSelectionGeneration();p.set("lsp.graphql-library","5.7.0");assertTrue(p.isGraphqlSelectionGenerationCurrent(n));p.set("runtime.graphql-node","22.23.3");assertFalse(p.isGraphqlSelectionGenerationCurrent(n))}
    @Test fun changedSelectionCannotEnterCreation(){val p=WorkspaceToolchainPreferences(RuntimeEnvironment.getApplication(),File("/graphql-fixture-${System.nanoTime()}"));val token=p.graphqlSelectionGeneration();p.set("runtime.graphql-node","22.23.3");var called=false;assertThrows(IllegalStateException::class.java){p.withGraphqlSelectionGeneration(token){called=true}};assertFalse(called)}
    @Test fun exactRegistryMutationRevokesOnlyGraphql(){val r=ManagedPackageRegistry(RuntimeEnvironment.getApplication());val before=r.list();val id="graphql-fixture-${System.nanoTime()}";val record=ManagedPackageRecord("lsp.graphql-library","5.7.0",ExecutionScope.LOCAL_LINUX_ARM64.name,"/app/packages/lsp.graphql-library/5.7.0/arm64-v8a",1234,metadata=mapOf("fixture" to id));val gql=r.graphqlPackageGeneration();val toml=r.tomlPackageGeneration();val vue=r.vuePackageGeneration();r.put(record);assertFalse(r.isGraphqlPackageGenerationCurrent(gql));assertTrue(r.isTomlPackageGenerationCurrent(toml));assertTrue(r.isVuePackageGenerationCurrent(vue));val current=r.graphqlPackageGeneration();r.put(record);assertTrue(r.isGraphqlPackageGenerationCurrent(current));r.replaceAll(before)}
    @Test fun unrelatedRegistryAndNoOpPreserveGraphql(){val r=ManagedPackageRegistry(RuntimeEnvironment.getApplication());val before=r.list();val token=r.graphqlPackageGeneration();r.replaceAll(before);assertTrue(r.isGraphqlPackageGenerationCurrent(token));val record=ManagedPackageRecord("runtime.node","graphql-fixture",ExecutionScope.LOCAL_LINUX_ARM64.name,"/app/packages/runtime.node/graphql-fixture/arm64-v8a",1);r.put(record);assertTrue(r.isGraphqlPackageGenerationCurrent(token));r.replaceAll(before)}
    @Test fun packageFinalAdmissionSerializesPublication(){val entered=java.util.concurrent.CountDownLatch(1);val release=java.util.concurrent.CountDownLatch(1);val finished=java.util.concurrent.CountDownLatch(1);val t=Thread{GraphqlGenerationAdmission.withAdmission{entered.countDown();release.await()}};t.start();assertTrue(entered.await(1,java.util.concurrent.TimeUnit.SECONDS));val r=ManagedPackageRegistry(RuntimeEnvironment.getApplication());val before=r.list();val writer=Thread{r.replaceAll(before);finished.countDown()};writer.start();assertFalse(finished.await(30,java.util.concurrent.TimeUnit.MILLISECONDS));release.countDown();assertTrue(finished.await(1,java.util.concurrent.TimeUnit.SECONDS));t.join();writer.join()}
}
